namespace Payments;

public sealed class SettlementBatchProcessor
{
    public SettlementResult Process(string merchantId, IEnumerable<PaymentItem> items, string settlementCurrency,
        decimal percentageFee, decimal fixedFee, decimal submissionLimit, ISettlementGateway gateway)
    {
        var (lines, accepted) = EvaluateItems(
            items, settlementCurrency, percentageFee, fixedFee, submissionLimit);

        if (accepted.Count == 0)
            return new SettlementResult(lines, 0m, "empty");

        if (string.IsNullOrWhiteSpace(merchantId))
            return CreateRejectedResult(lines, accepted, "invalid-merchant");

        var total = accepted.Sum(entry => entry.Net);
        var references = accepted.Select(entry => entry.Reference).ToArray();
        var gatewayResult = gateway.Submit(merchantId, settlementCurrency, total, references);

        if (!gatewayResult.Accepted)
            return CreateRejectedResult(lines, accepted, $"gateway-{gatewayResult.Code}");

        lines.AddRange(accepted.Select(entry => new SettlementLine(entry.Reference, entry.Net, "submitted")));
        var status = lines.Any(line => line.Status != "submitted") ? "partial" : "submitted";
        return new SettlementResult(lines, total, status);
    }

    private static (List<SettlementLine> Lines, List<AcceptedPayment> Accepted) EvaluateItems(
        IEnumerable<PaymentItem> items, string settlementCurrency, decimal percentageFee,
        decimal fixedFee, decimal submissionLimit)
    {
        var lines = new List<SettlementLine>();
        var accepted = new List<AcceptedPayment>();
        var seen = new HashSet<string>(StringComparer.Ordinal);

        foreach (var item in items)
        {
            var evaluation = EvaluateItem(item, settlementCurrency, percentageFee, fixedFee,
                submissionLimit, seen, accepted);

            if (evaluation.RejectionReason is not null)
                lines.Add(new SettlementLine(item.Reference, 0m, evaluation.RejectionReason));
            else
                accepted.Add(new AcceptedPayment(item.Reference, evaluation.Net));
        }

        return (lines, accepted);
    }

    private static ItemEvaluation EvaluateItem(PaymentItem item, string settlementCurrency,
        decimal percentageFee, decimal fixedFee, decimal submissionLimit, HashSet<string> seen,
        List<AcceptedPayment> accepted)
    {
        var validationFailure = GetValidationFailure(item, settlementCurrency, seen);
        if (validationFailure is not null)
            return ItemEvaluation.Rejected(validationFailure);

        var fee = decimal.Round(item.GrossAmount * percentageFee + fixedFee, 2);
        var net = decimal.Round(item.GrossAmount - fee, 2);

        if (net <= 0m)
            return ItemEvaluation.Rejected("fee-exceeds-amount");
        if (accepted.Sum(entry => entry.Net) + net > submissionLimit)
            return ItemEvaluation.Rejected("batch-limit");

        return ItemEvaluation.Accepted(net);
    }

    private static string? GetValidationFailure(PaymentItem item, string settlementCurrency,
        HashSet<string> seen)
    {
        if (string.IsNullOrWhiteSpace(item.Reference))
            return "invalid-reference";
        if (!seen.Add(item.Reference))
            return "duplicate";
        if (!string.Equals(item.Currency, settlementCurrency, StringComparison.OrdinalIgnoreCase))
            return "currency-mismatch";
        if (item.GrossAmount <= 0m)
            return "invalid-amount";
        if (item.Refunded)
            return "refunded";
        if (item.Held)
            return "held";

        return null;
    }

    private static SettlementResult CreateRejectedResult(List<SettlementLine> lines,
        List<AcceptedPayment> accepted, string reason)
    {
        var rejectedLines = accepted.Select(entry => new SettlementLine(entry.Reference, 0m, reason));
        return new SettlementResult([.. lines, .. rejectedLines], 0m, "rejected");
    }

    private readonly record struct AcceptedPayment(string Reference, decimal Net);

    private readonly record struct ItemEvaluation(string? RejectionReason, decimal Net)
    {
        public static ItemEvaluation Rejected(string reason) => new(reason, 0m);

        public static ItemEvaluation Accepted(decimal net) => new(null, net);
    }
}
